BATCH = {
(28,114):{'topic':'vvcTreatmentCombo','lead':'ترشحات سفید غلیظ چسبیده به دیوار واژن + خارش و سوزش + ادم/اریتم ولویواژن: کاندیدیاز ولوواژینال و پاسخ درمانی، آزول‌های موضعی سه تا پنج/هفت روز.',
'interpretation':'درد سوزش ادرار و خارش همراه با ترشح‌های غلیظ سفید «پنیری‌مانند» و علامت التهاب ولویواژن، تصویر معمول کاندیدیاز است؛ تریکومونا ترشح چرمی-زرد و «سرویکس توت‌فرنگی» می‌دهد و BV ترشح همگن رقیق بدون التهاب برجسته است و گونوکوک ترشح چرمی سرویکسی می‌دهد و سرویکس طبیعی نیست؛ درمان کاندیدیاز با ایمیدازول‌های موضعی سه تا هفت شبه (یا تزریقی در صورت پشتیبانی شریک/عود) بهترین پاسخ است.',
'reasons':['تشخیص کاندیدیاز و درمان ایمیدازول موضعی درست است؛ پاسخ صحیح.','تریکومونا ترشح زرد بدبو با سرویکس توت‌فرنگی می‌دهد نه پروفایل بالینی این بیمار.','BV ترشح رقیق همگن بدون علایم التهاب برجسته دارد.','گونوره بیش‌تر به‌عنوان عامل عفونت سرویکس مطرح است نه این تصویر.']},
(28,115):{'topic':'teratogenWindow','lead':'بیش‌ترین حساسیت جنین برای تشکیل آنومالی اصلی از اثر عوامل تراتوژن، در هفته‌های ۴ تا ۱۰ (پنجرهٔ ارگانوژنز) از حاملگی است.',
'interpretation':'هفته‌های ۳ تا ۸-۱۰ از لقاح، زمان شکل‌گیری ارگان‌هاست و بیش‌ترین تأثیر ساختاری تراتوژن‌ها در همین بازه می‌افتد؛ تماس پیش از لانه‌گزینی اثر «همه‌یا‌هیچ» دارد و تماس‌های بعدی بیش‌تر به رشد و عملکرد سیستم‌ها لطمه می‌زنند؛ راه دارو (خوراکی/تزریقی) تعیین‌کنندهٔ اصلی میزان اثر نیست.',
'reasons':['سه‌ماههٔ اول به‌طور کلی درست است ولی چارچوب دقیقِ افزایش خطر، هفته‌های ۴ تا ۱۰ است.','۴ تا ۱۰ هفتگی پنجرهٔ ارگانوژن و خطر ساختاری بیشینه است؛ پاسخ صحیح.','۲ تا ۳ هفته پس از لقاح دورهٔ «همه‌یا‌هیچ» است و ناهنجاری‌های متعدد را ایجاد نمی‌کند.','مسیر مصرف دارو تعیین‌کنندهٔ اصلی تراتوژنی بودن نیست.']},
(28,116):{'topic':'hivPregTreatment','lead':'در پرسش «صحیح نیست» برای HIV بارداری بر اساس پروتکل زمان طرح سؤال، گزینهٔ شروع درمان «از همان ابتدای بارداری» در همهٔ بیماران به‌عنوان گزارهٔ غلط کلید خورده است.',
'interpretation':'اهداف مدیریت HIV بارداری کاهش انتقال عمودی با ترکیب‌های ضدویروسی و انتخاب روش زایمان بر اساس وضعیت ویروس و غول است؛ در پروتکل‌های زمان طرح سؤال، تصمیم شروع درمان بر پایهٔ شمارش CD4 و بار ویروسی گرفته می‌شد و عبارت «از همان ابتدا برای همهٔ بیماران» گزارهٔ انتخاب‌شدهٔ سؤال (به‌معنی گزارهٔ غلط) بوده‌است؛ کاهش انتقال با ضدویروس‌بندی و نقش زیدووودین در همان متن امضاء شده‌است.',
'reasons':['کاهش انتقال به جنین با ضدویروس گزارهٔ درست این متن است.','شروع درمان از همان ابتدا در همهٔ بیماران، طبق کلید این پرسش گزارهٔ غلط شمرده می‌شود؛ پاسخ صحیح (گزینهٔ موردنظر «صحیح نیست»).','ترجیح سزارین در پردهٔ سالم در متن پروتکلی این سؤال جایگاه داشته‌است.','زیدووودین در متن‌های معتبر از کم‌عارضه‌ترین گزینه‌های بارداری شمرده می‌شد و درست است.']},
(28,117):{'topic':'earlyRadiationExposure','lead':'تماس پیش از لانه‌گزینی (دو هفتهٔ نخست) با اصل «همه‌یا‌هیچ» تفسیر می‌شود یا مرگ جنین یا بارداری طبیعی بدون آنومالی.',
'interpretation':'در پرتوافکنی‌های انجام‌شده پیش از لانه‌گزینی (تقریباً ۱۴ روز اول پس از لقاح)، سلول‌های توتی‌پوتان در برابر آسیب یا می‌میرند یا به‌طور کامل ترمیم می‌شوند و اثر تراتوژنیک مورد انتظار نیست؛ بنابراین در صورت آسیب غیرقابل‌ترمیم پیامد محتمل، مرگ جنین/سقط اولیه است و ناهنجاری‌های مادرزادی چندگانه به فاز ارگانوژن (هفته‌های ۳ تا ۸) مربوط می‌شوند و لوسمی‌های کودکی اثر دور و نادرتر است.',
'reasons':['لوسمی‌های دوران کودکی اثر دور و کم‌احتمال‌تر این موقعیت‌اند.','اصل «همه‌یا‌هیچ» ناهنجاری تراتوژنیک را منتفی می‌کند ولی در گزینه‌بندی این سؤال پاسخ مرجع، مرگ جنین در صورت آسیب شدید است.','در اثر «همه‌یا‌هیچ» پیامد محتمل در صورت آسیب غیرقابل‌ترمیم مرگ جنین است؛ پاسخ صحیح.','ناهنجاری‌های متعدد مادرزادی مخصوص فاز ارگانوژن است نه پیش از لانه‌گزینی.']},
(28,119):{'topic':'earlyPregSerialHcg','lead':'HCG=۹۸۰ با سونوگرافی ترانس‌واژینال بدون بارداری داخل‌رحمی و بدون تودهٔ آدنکس: تیتر زیر ناحیهٔ تفکیک است و قدم درست، سلایر BHCG در ۴۸ ساعت بعد.',
'interpretation':'با تیتر ۹۸0 که زیر آستانهٔ ناحیهٔ تفکیک معمول (۱۵۰۰-۲۰۰۰ برای سونوگرافی ترانس‌واژینال) است، نبود ساک حاملگی داخل‌رحمی هنوز دال بر قطعیت نیست و بارداری با محل نامعلوم با BHCG سریال پیگیری می‌شود: صعود بیش از ~۵۰٪ در ۴۸ ساعت به‌نفع حاملگی داخل‌رحمی سالم، الگوی کاهش یا استاندارد در سقط و الگوی متزلزل/ناکافی در EP است؛ تکرار سونوگرافی در همان تیتر بدون مرجع روند BHCG معمولاً کمک‌کننده نیست و متوترکسات بدون اثبات EP و رد بارداری داخل‌رحمی قابل‌استفاده نیست و لاپاروسکوپی اورژانس فقط در علایم ناپایدار است.',
'reasons':['تکرار سونوگرافی در همین تیتر معمولاً هنوز غیرقطعی است.','سلایر BHCG در ۴۸ ساعت بعد قدم منطقی است؛ پاسخ صحیح.','متوترکسات بدون تأیید بارداری خارج‌رحمی و رد بارداری طبیعی نباید مصرف شود.','لاپاروسکوپی اورژانس در بیمار پایدار لازم نیست.']},
(28,120):{'topic':'agusWorkup','lead':'پاپ‌اسمیر AGUS در زن ۴۷ ساله: به‌خاطر خطر آدنوکارسینوم آندومتر/آندوسرویکس، جزو ارزیابی الزامی، نمونه‌برداری آندومتر است.',
'interpretation':'گزارش سلول‌های غده‌ای آتیپیکال با معناداری نامشخص (AGUS) خطر آدنوکارسینوم در آندومتر و آندوسرویکس را بالا می‌برد و الگوی کارآپ معمول شامل کولپوسکوپی+ECC و نمونه‌برداری آندومتر (در زنان ≥۳۵ سال یا با سابقهٔ خون‌ریزی غیرطبیعی) است؛ تکرار سادهٔ پاپ‌اسمیر یا درمان استروژن موضعی بدون نمونه‌برداری ناکافی است و تصمیم کولپوسکوپی/هیستروسکوپی به‌تنهایی جای آندومتر را نمی‌گیرد.',
'reasons':['تکرار پاپ‌اسمیر در AGUS به‌تنهایی کافی نیست.','کورتاژ تشخیصی تهاجمی‌تر است و بیوپسی آندومتر پلهٔ اول این کارآپ است.','بیوپسی آندومتر برای سلول‌های غده‌ای در این سن درست است؛ پاسخ صحیح.','هیستروسکوپی در صورت نیاز مرحلهٔ بعد است.']},
(28,121):{'topic':'firstPrenatalVisitContent','lead':'ترکیب استاندارد ویزیت اول بارداری (۱۲ هفته): تجویز اسید فولیک + آزمایشات روتین بارداری + درخواست غربالگری سه‌ماههٔ اول.',
'interpretation':'در پنجرهٔ سه‌ماههٔ اول، ویزیت اول بارداری شامل ثبت شرایط و آزمایش‌های روتین، تجویز اسید فولیک (دست‌کم تا پایان سه‌ماههٔ اول) و درخواست غربالگری ترکیبی سه‌ماههٔ اول (NT و سرولوژی) است؛ اقدامات مثل سونوگرافی برای تعیین سن دقیق زمانی لازم است که تاریخ قاعدگی نامشخص باشد و سایر ترکیب‌ها یا ناقص‌اند یا اقداماتی برای دوره‌های دیگر دارند.',
'reasons':['این گزینه با الحاق بخشٔ دیابت‌مرتبط ناهماهنگ است و ترکیب استاندارد کامل نیست.','سونوگرافی تعیین سن دقیق بدون غربالگری ترکیبی، ساختار کامل پنجرهٔ اول نیست.','اسید فولیک + آزمایشات روتین + غربالگری سه‌ماههٔ اول ترکیب کامل است؛ پاسخ صحیح.','واکسیناسیون به این شکل بخشی از دستور ویزیت اول نیست.']},
(28,122):{'topic':'primaryAmenorrheaWorkup','lead':'آمنورهٔ اولیه با دستگاه ژنیتال و تصویر طبیعی و TSH/PRL طبیعی: قدم بعدی اندازه‌گیری LH و FSH برای تفکیک نارسایی تخمدان (هایپرگنادوتروپ) از به نارسایی مرکزی (هیپوگنادوتروپ).',
'interpretation':'در آمنورهٔ اولیه، اولین لایهٔ تفکیک پس از ارزیابی آناتومی و حذف علل پرولاکتینی/تیروئیدی، سنجش گنادوتروپین‌هاست: FSH/LH بالا نشانهٔ نارسایی اولیهٔ تخمدان (و کاریوتایپ پلهٔ بعدی است) و پایین معطوف به محور هیپوتالاموس-هیپوفیز (MRI مغز پلهٔ بعدی)؛ بنابراین در این بیمار با زایری طبیعی و TSH/PRL طبیعی، سنجش LH/FSH منطقی‌ترین قدم بعدی است.',
'reasons':['CT لگن برای ارزیابی علل آمنوره در این مرحله ارزش افزوده ندارد.','MRI مغز بعداً و بر اساس سطح گنادوتروپین‌ها انجام می‌شود.','اندازه‌گیری LH/FSH قدم صحیح بعدی است؛ پاسخ صحیح.','کاریوتایپ پس از FSH تصمیم‌ساز است نه به‌عنوان تست اول.']},
(28,123):{'topic':'ocpAllowedWithCaution','lead':'در میان این فهرست، تنها وضعیت سازگار با تجویز OCP با پایش دقیق «سابقهٔ کله‌سیستکتومی» است؛ DVT سابقه، همانژیوم کبدی و بی‌حرکتی پس از شکستگی لگن با OCP خطرناک است.',
'interpretation':'منع‌های جدی OCP شامل سابقهٔ ترومبوآمبولی وریدی، بیماری فعال کبد (همانژیوم نیز در فهرست احتیاط/منع برخی راهنماها) و بی‌حرکتی/دورهٔ خطر ترومبوز است؛ سابقهٔ سنبله/کله‌سیستکتومی (برداشتن کیسهٔ صفرا) نه به‌خودی‌خود منع است ولی مستلزم پایش عملکرد کبد است و «با نظارت دقیق» با آن سازگار است.',
'reasons':['سابقهٔ انسداد ورید عمقی با قرص ترکیبی منع مصرف مطلق است.','همانژیوم کبدی در فهرست احتیاط/منع OCP قرار می‌گیرد.','بی‌حرکتی پس از شکستگی لگن با OCP خطر ترومبوز را زیاد می‌کند.','سابقهٔ کله‌سیستکتومی شدید نیست و با پایش می‌توان OCP داد؛ پاسخ صحیح.']},
(28,124):{'topic':'severePreeclampsiaFeatures','lead':'پره‌اکلمپسی شدید ۳۵ هفته با پلاکت ۸۰ هزار، آنزیم‌های کبدی چندبرابر و الیگوری ۳۰۰ سی‌سی/۲۴h: تصمیم قطعی ختم فوری بارداری (به همراه سولفات منیزیم/کورتون) نه نگه‌داشتن به‌منظور بلوغ ریه.',
'interpretation':'چندمعیار شدید هم‌زمان (فشار ۱۶۰/۱۱۰، ترومبوسیتوپنی <۱۰۰۰۰۰، افزایش بازرزی‌های کبدی و کاهش حجم ادرار نشانگر آسیب کلیوی) در ۳۵ هفته، تعجیل در ختم بارداری را می‌طلبد و انتظار بر اساس کورتون به‌طور دیررس ۴۸ ساعته، خطر اکلمپسی و اختلال عملکرد ارگان را بالا می‌برد؛ سونوگرافی بیوفیزیکال گزارش وضع ژنینی می‌دهد ولی مسیر تصمیم‌گیری مادر را عوض نمی‌کند و داروهای فشار+دیورتیک جای ختم قطعی را نمی‌گیرد.',
'reasons':['تجویز استروئید و تعلل ۴۸ ساعته در این سطح علایم شدید اشتباه است.','BPP در تصمیم مادر در پره‌اکلمپسی شدید نقش تعیین‌کننده ندارد.','ختم فوری بارداری در چندعلایم شدید درست است؛ پاسخ صحیح.','سی‌نقل فشار و دیورتیک جای ختم را نمی‌گیرد.']},
(28,125):{'topic':'fibroidFeaturesExcept','lead':'فیبروم‌های رحمی بیش‌تر خون‌ریزی را به‌صورت «منوراژی» افزایش می‌دهند و الیگومنوره جزو اثرهای معمول آن‌ها نیست.',
'interpretation':'انواع میوم بر اساس موقعیت (ساب‌موکوزال/اینترامورال/ساب‌سروزال) اثرهای متفاوت دارند؛ ساب‌موکوزال به‌خاطر نزدیکی به حفرهٔ آندومتر بیش‌ترین اثر بر بارداری و خون‌ریزی را دارد و میوم با منوراژی (نه الیگومنوره) همراه است؛ زایمان زودرس، اضطراب اولیه و دژنراسیون در بارداری (که معمولاً با جراحی فوری نیازی نیست) از پیامدهای شناخته‌شدهٔ میوم در بارداری است.',
'reasons':['فیبروم ساب‌موکوزال بیش‌ترین اثر را بر بارداری دارد و درست است.','زایمان زودرس از عوارض حاملگی با فیبروم است و درست است.','الیگومنوره اثر معمول فیبروم نیست؛ پاسخ صحیح («صحیح نیست»).','دژنرسانس فیبروم در بارداری معمولاً فوریت جراحی ندارد.']},
(28,126):{'topic':'posScreenAmnio','lead':'غربالگری مثبت سه‌ماههٔ اول: مرحلهٔ بعدی آزمون تشخیصی (نمونه‌برداری تهاجمی) است و در چارچوب کلاسیک این سؤال آمنیوسنتز انتخاب کلید است.',
'interpretation':'غربالگری مثبت سه‌ماههٔ اول به‌معنی تخمین بالای خطر کروموزومی است و باید با آزمون تشخیصی قطعی دنبال شود؛ در کتاب‌های مرجع کلاسیک، «آمنیوسنتز» در پنجرهٔ ۱۵-۲۰ هفته روش تشخیصی تعیین‌شدهٔ رایج محسوب می‌شویمکند (CVS فقط در بازهٔ ۱۰-۱۳⁺⁶ قابل‌اجراست و با توجه به زمان ارجاع مشخص‌شده در این سناریو، آمنیوسنتز انتخاب کلید است)؛ ختم بارداری ب حجناسقط با ارجاع مشاورهٔ ژنتیک عجولانه است و سونوگرافی موجودیت آنومالی مکمل است نه جایگزین.',
'reasons':['ختم بارداری فقط با تست غربالگری مثبت غیراصولی است.','سونوگرافی دقیق مکمل است نه جایگزین آزمون تشخیصی.','آمنیوسنتز روش تشخیصی تعیین‌شدهٔ کلید است؛ پاسخ صحیح.','CVS فقط در بازهٔ اولیهٔ مشخص قابل‌بحث است.']},
(28,127):{'topic':'pregnancyVaccines','lead':'سرخجه (بخشی از MMR) در بارداری ممنوع است؛ هپاتیت B، آنفلوآنزا و کزاز/تتانوس غیرزنده‌اند و در بارداری با اندیکاسیون مجازند.',
'interpretation':'واکسن‌های زندهٔ تضعیف‌شده (سرخجه/اوریون MMR، واریسلا و تب‌زرد) در بارداری به‌خاطر خطر نظری عفونت جنینی ممنوع‌اند؛ هپاتیت B (پروتئینی)، آنفلوآنزای کشتهٔ تزریقی و واکسن ترکیب کزاز-دیفتری از گروه غیرزنده‌اند و در بارداری در صورت نیاز مجازند و مثل کزاز حتی فعال توصیه می‌شوند.',
'reasons':['هپاتیت B واکسن غیرزنده است و با خطر مجاز است.','آنفلوآنزا فصلی کشتهٔ تزریقی توصیه می‌شود.','سرخجه واکسن زنده است و در بارداری ممنوع؛ پاسخ صحیح.','کزاز/تتانوس و دیفتری غیرزنده است و در بارداری مجاز است.']},
(28,128):{'topic':'pretermLaborBundle','lead':'زایمان زودرس با تغییر سرویکس (انقباض ۲× در ۲۰ دقیقه + دیالتاسیون ۲ سانتی‌متر + افاسمان ۸۰٪): بستری + توکولیتیک + کورتون برای به تعویق انداختن زایمان و بلوغ ریه.',
'interpretation':'زایمان زودرس واقعی با انقباض‌های مؤید همراه با تغییر سرویکس تعریف می‌شود و وقتی جنین قابل‌نجات باشد، باید با بستری، توکولیتیک کوتاه‌مدت (مثل نیفی‌دیپین/ایندومتاسین) و بتامتازون/دگزامتازون برای بلوغ ریه مدیریت شود و در صورت عفونت یا ناپایداری مسیر متفاوت خواهد شد؛ ختم فوریت یا درمان سرپایی با این میزان تغییر سرویکس عجولانه و ناکافی است.',
'reasons':['سرکلاژ در حضور انقباض فعال پس از شروع زایمان زودرس منع است.','کورتون+ختم بلافاصله در غیاب علت خاص اشتباه است.','درمان سرپایی عفونت ادراری کارآپ این سناریو نیست.','بستری + توکولیتیک + کورتون پاسخ استاندارد است؛ پاسخ صحیح.']},
(28,129):{'topic':'syphilisScreenConfirm','lead':'در متن برنامهٔ غربالگری بارداری، VDRL مثبت عنوان دو قدم است: ابتدا تأیید با آزمون اختصاصی ترپونمی (FTA-Abs) سپس تعیین وضعیت درمان.',
'interpretation':'مثلث غربالگری سیفلیس دوگانه است: تست‌های غیرترپونمی (VDRL/RPR) حساس و تست‌های ترپونمی (FTA-Abs/TPHA) اختصاصی تأیید هستند و در بارداری با درد به‌عنوان علت و با تصمیم درمانی مستقیم (که همیشه پنی‌سیلین است) مقصد است؛ درعمل، در بارداری اگر VDRL مثبت شود، تأیید اختصاصی و ارزیابی بالینی فوری انجام می‌شود (و در بسیاری از شیوه‌های واقعی درمان شروع می‌شود ولی کلید این پرسش مرحلهٔ تأیید را اول می‌چیند) و اریترومایسین در این بارداری گزینهٔ مناسب نیست.',
'reasons':['بررسی سایر عفونت‌های مقاربتی بخش مکمل است نه قدم اول.','درمان با پنی‌سیلین پس از تأیید آزمایشگاهی انجام می‌شود.','اریترومایسین در بارداری برای سیفلیس جایگاه قوی ندارد.','تأیید با FTA-Abs قدم اصولی بعدی است؛ پاسخ صحیح.']},
(28,130):{'topic':'imperforateHymen','lead':'احتباس ادرار + دردهای لگنی مکرر در نوجوان با برجستگی بنفش زیر مجرای ادرار در معاینه: هایمن بدون سوراخ (واکوماتوکلپوس شکل‌گرفته).',
'interpretation':'جمع‌شدن خون قاعدگی پشت غشای هایمن، تودهٔ بنفش-آبی برجسته در ورودی واژن (زیر مجرا) می‌سازد و به‌لحاظ پیوستگی مثانه می‌تواند احتباس ادرار و درد لگنی دوره‌ای ایجاد کند؛ سپتوم عرضی مکانیک به‌خصوص در فورشت/میان‌واژن است و معمولاً بدون این برجستگی کلاسیک مشاهده می‌شود و دیورتیکول بورترا/راکی‌تاسکی نیز این تابلوی بنفش را نمی‌سازند.',
'reasons':['هایمن بدون سوراخ با این ترکیب تشخیص داده می‌شود؛ پاسخ صحیح.','سپتوم عرضی معمولاً برجستگی بنفش بارز در اول واژن نمی‌سازد.','دیورتیکول بورترا در این سن جریان معمولی نیست.','راکی‌تاسکی با نبود رحم می‌آید نه احتباس خون دوره‌ای.']},
(28,131):{'topic':'infertilitySemenFirst','lead':'در کارآپ زوج نابارور، آسان‌ترین و ارزان‌ترین و غیرتهاجمی‌ترین تست شروع، اسپرموگرام مرد است — و معمولاً همزمان/در صدر توصیه می‌شود.',
'interpretation':'معیار شروع آنالیز اسپرم این است که علت مردانه در بخش قابل‌توجهی از نازایی‌ها مسئول است و این تست ساده و غیرتهاجمی، قابلیت اصلی تعیین مسیر بعدی (تست‌های تخمکی/لوله‌ای در صورت طبیعی بودن) را دارد؛ تست پس از مقاربت از برنامه‌های قدیمی و لاپاروسکوپی و تحریک تخمک‌گذاری، بسởی از پایه‌گذاری اولیه است.',
'reasons':['اسپرموگرام اولین تست کارآپ است؛ پاسخ صحیح.','تست پس از نزدیکی بخشی از کارآپ قدیمی است نه قدم اول.','لاپاروسکوپی در پلهٔ پایانی کارآپ (پس از ارزیابی لوله) قرار دارد.','تحریک تخمک‌گذاری بدون شناخت علت معقول نیست.']},
(28,132):{'topic':'myomaMostCommonSymptom','lead':'شایع‌ترین شکایت اختلال‌آفرین در میوم رحمی، منوراژی (افزایش حجم خون‌ریزی قاعدگی) است، مخصوصاً با میوم‌های ساب‌موکوزال/اینترامورال.',
'interpretation':'بیش‌ترین شکایت بیماران با میوم رحمی، خون‌ریزی شدید قاعدگی (منوراژی) است که می‌تواند به کم‌خونی بینجامد و بیش‌تر با میوم‌های ساب‌موکوزال یا اینترامورال بزرگ همراه است؛ خون‌ریزی قبل از قاعدگی، خون‌ریزی پس از نزدیکی یا دیسمنورهٔ شدید به‌تنهایی سبب مراجعهٔ کم‌تر شایعی‌اند.',
'reasons':['منوراژی شایع‌ترین شکایت میوم است؛ پاسخ صحیح.','خون‌ریزی بین‌قاعدگی/پیش‌قاعدگی کم‌تر شایع است.','خون‌ریزی پس از نزدیکی بیش‌تر مرتبط با آسیب سرویکس/واژن است.','درد موقع قاعدگی (دیسمنوره) می‌تواند همراه باشد ولی منوراژی مقدم‌تر است.']},
(28,133):{'topic':'atrophicVaginitisSymptoms','lead':'دیزوری، تکرر ادرار و شب‌ادراری در زن ۷۰ سالهٔ یائسه با کشت منفی: آتروفی ژنیتو-ادراری ( ترشح استروژن موضعی مناسب‌ترین اقدام).',
'interpretation':'در یائسه، تحلیل اپیتلیوم مجاری ادراری و واژن به‌دلیل کمبود استروژن می‌تواند علایم تحریکی ادراری (دیزوری، تکرر، اورژنسی، شب‌ادراری) بدهد و با منفی شدن کشت، منشأ التهابی حذف می‌شود؛ استروژن موضعی (کرم/حلقه‌واژینال) پاسخ انتخابی است و ایمی‌پرامین/سیپروفلوکساسین/کلونیدین هر کدام اندیکاسیون‌های متفاوتی دارند.',
'reasons':['سیپروفلوکساسین بدون کشت مثبت/علت عفونی مؤید نیست.','ایمی‌پرامین برای مثانهٔ بی‌قرار در این زمینه انتخاب اولیه نیست.','استروژن موضعی در آتروفی یائسه درست است؛ پاسخ صحیح.','کلونیدین در این شکایت ادراری کاربرد متعارف ندارد.']},
(28,134):{'topic':'trichomoniasisSigns','lead':'ترشحات زرد بدبوی فراوان + خارش/سوزش + سرویکس با نمای «توت‌فرنگی»: تریکوموناز ولوواژینال است.',
'interpretation':'ترشح زرد-سبز کف‌آلود همراه خارش و سوزش و یافتن سرویکس نقطه‌چین «توت‌فرنگی» (از خون‌خوردگی مخاطی) مخصوص تریکوموناز است؛ کاندیدا ترشح پنیری با التهاب ولوی دارد و سرویکس را «توت‌فرنگی» نمی‌کند، گاردنلا/BV ترشح رقیق‌تر بدون التهاب برجسته دارد و گونوره سرویکس سیتیس چرمی خاموش می‌سازد.',
'reasons':['کاندیدا با ترشح پنیری و pH طبیعی می‌آید.','گاردنلا با ترشح رقیق و سلول سرنخ می‌آید نه سرویکس توت‌فرنگی.','تریکومونا با این یافته‌ها محتمل‌ترین است؛ پاسخ صحیح.','گونوره جزو علت سرویکسی‌یت است نه این تصویر.']},
(28,135):{'topic':'previaBleedingDelivery','lead':'جفت سرراهی در ۳۶ هفته با خون‌ریزی واژینال فعال: حتی با فشار نرمال و ضربان قلب جنین طبیعی، به‌خاطر خطر ایجاد مجدد هموراژی، زایمان با سزارین شایسته است.',
'interpretation':'جفت سرراهی کامل یک اندیکاسیون قطعی سزارین است و در ۳۶ هفته با خون‌ریزی فعال، مدل مدیریت انتظاری دیگر پذیرفتنی نیست؛ سولفات منیزیم در این را নিয়م ندارد، «تحت نظر قرار دادن» در بیمارسرا خطر جریان مجدد خون‌ریزی بدون پایش داخلی حفاظتی است و اینداکشن در جفت سرراهی کامل ممنوع است.',
'reasons':['سولفات منیزیم در کنترل خون‌ریزی جفت سرراهی جایگاهی ندارد.','تحت نظر در جفت سرراهی فعال‌خون‌ریزی ۳۶ هفته ریسکی است.','سزارین در جفت سرراهی کامل فعال صحیح است؛ پاسخ صحیح.','اینداکشن زایمان در جفت سرراهی کامل ممنوع است و به‌خطر می‌افتد.']},
(28,136):{'topic':'gtnRuleOutNewPregnancy','lead':'صعود BHCG دو ماه پس از تخلیهٔ مول: قبل از هر دخالت GTN، بارداری مجدد را رد کن چون بارداری طبیعی جدید نیز BHCG صعودی می‌دهد.',
'interpretation':'روند BHCG پس‌از-تخلیهٔ مول باید نزولی باشد و هر صعود پلاتو/انفجار صعودی به‌نفع GTN است، اما عامل اولیهٔ قابل‌تقابل، تشکیل حاملگی جدید (عامل اصلی صعود مجدد) است که بدون رد آن درمان شیمیایی تجویز نمی‌شود؛ بررسی متاستاز و کموتراپی در مراحل بعدی قرار می‌گیرد و سونوگرافی لگن به‌تنهایی پاسخ‌گوی علت صعود BHCG نیست.',
'reasons':['بررسی متاستاز بعد از رد بارداری جدید مؤید است.','کموتراپی فقط پس از تأیید GTN شروع می‌شود.','رد بارداری مجدد پیش از تشخیص GTN قدم اول است؛ پاسخ صحیح.','سونوگرافی لگن علت صعود را تشخیص نمی‌دهد.']},
(28,137):{'topic':'oligohydramniosRenal','lead':'الیگوهیدرامنیوس پس از ۲۰ هفته: ادرار جنین منبع اصلی آب آمنیوتیک است و اولین راستی‌آزمایی، بررسی سیستم کلیه/ادراری جنینی (آژنزی کلیه، انسداد، دیس‌پلازی کیستیک) است.',
'interpretation':'در نیمهٔ دوم بارداری، مایع آمنیوتیک به‌تدریج از ادرار جنین ساخته می‌شود و کاسته‌شدن شدید آن بیش‌تر از جنس آسیب تولید/دفع ادرار جنینی است؛ ناهنجاری‌های قلب بیش‌تر با هیدروپس همراه‌اند، انسداد دستگاه گوارش با پلی‌هیدرامنیوس می‌آید و اختلالات CNS نیز در الگوی مصرف مایع (دگلوت کردن ناکافی) نقشی در الیگوهیدرامنیوس ندارند.',
'reasons':['بررسی آنومالی کلیوی در الیگوهیدرامنیوس درست است؛ پاسخ صحیح.','آنومالی قلبی بیش‌تر با هیدروپس همراه است.','انسداد دستگاه گوارش با پلی‌هیدرامنیوس می‌آید نه الیگوهیدرامنیوس.','ناهنجاری CNS الگوی ربط مستقیمی با کم‌شدن مایع ندارد.']},
(28,138):{'topic':'pphMostCommonCause','lead':'آتونی رحمی شایع‌ترین علت خون‌ریزی پس از زایمان (حدود ۷۰-۸۰٪ موارد) است و انواع شدید نیز وقتی برآیند علل ترکیبی شود باقی می‌ماند.',
'interpretation':'در چهار T علل خون‌ریزی پس از زایمان (Tone/Trauma/Tissue/Thrombin)، بیش‌ترین سهم با آتونی رحم (ضعف تون عضلانی با شل‌ماندن رحم) است و پارگی دستگاه تناسلی، بقایای جفت و اختلالات انعقادی پس‌اندازنده‌های بعدی‌اند؛ این ترتیب مبنای اولویت‌بندی اولین اقدام درمانی (ماساژ دو دستی + اکسی‌توسین) است.',
'reasons':['آتونی رحم شایع‌ترین علت است؛ پاسخ صحیح.','پارگی‌های دستگاه ژنیتال دومین علت در اکثر آمارهاست.','اختلالات انعقادی از علل کم‌تر شایع خون‌ریزی پس از زایمان‌اند.','باقی‌ماندن جفت علت مهم است ولی از آتونی کم‌تر فراوانی دارد.']},
(28,139):{'topic':'epRupturedSurgery','lead':'سنکوپ + هیپوتانسیون ارتوستاتیک + تندرنس و ریباند با تست مثبت بارداری: EP پاره‌شدهٔ داخل‌شکمی با ناپایداری همودینامیک — لاپاراتومی اورژانس.',
'interpretation':'علایم شوک (سنکوپ، افت فشار ارتوستاتیک) به‌همراه علایم تحریک پریتونه‌آل (ریباند) در زن‌باردارِ مثبت، خون‌ریزی داخل‌شکمی فعال ناشی از پارگی بارداری خارج‌رحمی را مطرح می‌کند و پایدارسازی همزمان و عمل اورژانس (لاپاراتومی/لاپاروسکوپی با توجه به مهارت و دسترسی) لازم است؛ سونوگرافی در این سطح ناپایداری فقط زمان ازدست‌رفته‌است، تیتراژ سریالی نامتعارف است و لاپاروسکوپی الکتیو به‌منزلهٔ تأخیر است.',
'reasons':['لاپاراتومی اورژانس در EP پاره‌شدهٔ ناپایدار درست است؛ پاسخ صحیح.','سونوگرافی در ناپایداری همودینامیک زمان‌بر است.','تیتراژ سری در این سطح از ناپایداری خطرناک است.','لاپاروسکوپی الکتیو مفهوم تعویق را در این فوریت دارد.']},
(28,140):{'topic':'endoHyperplasiaMalignancy','lead':'ریسک تبدیل هایپرپلازی آندومتر به سرطان در «هایپرپلازی کمپلکس همراه آتی‌پی» بیش‌ترین است.',
'interpretation':'رده‌بندی هایپرپلازی آندومتر بر اساس پیچیدگی معماری (ساده/کمپلکس) و آتی‌پی سلولی است و تحول بدخیم عمدتاً توسط آتی‌پی تعیین می‌شود؛ ترکیب پیچیدهٔ کمپلکس با آتی‌پی بالاترین درصد پیشرفت به آدنوکارسینوم (در برخورد رویت‌ها تا حدود یک‌سوم موارد) را دارد و فرم‌های بدون آتی‌پی ریسک بسیار پایین‌تری دارند.',
'reasons':['هایپرپلازی ساده بدون آتی‌پی ریسک پایینی دارد.','هایپرپلازی کمپلکس بدون آتی‌پی ریسک متوسطی دارد.','آتی‌پی ساده نیز وزنی در تبدیل دارد ولی کم‌تر از فرم کمپلکس با آتی‌پی است.','کمپلکس با آتی‌پی بیش‌ترین ریسک تبدیل را دارد؛ پاسخ صحیح.']},
(28,141):{'topic':'dysgerminomaChild','lead':'تودهٔ کمپلکس تخمدانی + بلوغ زودرس و LDH ۲ برابر حد طبیعی در دختر ۸ ساله: دیس‌ژرمینوما در صدر احتمالات.',
'interpretation':'در دختران نونهال، تومورهای سلول جنینی تخمدان شایع‌ترین نوع بدخیمی تخمدان‌اند و دیس‌ژرمینوما با مارکر LDH بالا مشخص می‌شود و می‌تواند با علایم ناشی از استروژن (بلوغ زودرس کاذب در برخی زیرگروه‌ها/هموراژی) مراجعه کند؛ تومور کیسهٔ زرده با AFP بالا می‌آید و کوریوکارسینوما با BHCG و تراتوم نابالغ معمولاً بی‌لدوز متغیر است و در این سن کمتر الگوی بلوغ زودرس را می‌دهد.',
'reasons':['دیس‌ژرمینوما با بالا بودن LDH در این سن کلیدی است؛ پاسخ صحیح.','تومور کیسهٔ زرده با AFP بالا می‌آید نه LDH غالب.','کوریوکارسینوما با سطح بالای BHCG همراه است نه LDH غالب.','تراتوم نابالغ مارکرهای متغیر دارد و بلوغ زودرس کم‌تر دارد.']},
(28,142):{'topic':'eclampsiaMgFirst','lead':'تشنج در بارداری با فشار ۱۸۰/۱۰۰ در ۲۲ هفته: اکلمپسی و بهترین داروی گیاه‌کنندهٔ تشنج، سولفات منیزیم وریدی.',
'interpretation':'اکلمپسی تعریف وقوع تشنج تونیک-کلونیک در چارچوب پره‌اکلمپسی است و سولفات منیزیم به‌خاطر اثربخشی بیش‌تر و عوارض کم برای مادر/جنین و قابلیت جلوگیری از عود، داروی خط اول است؛ فنی‌توئین و فنوباربیتال اگر تشنج مقاوم به Mg یا منع Mg باشد انتخاب دوم‌اند و دیازپام رکتال در این چارچوب فقط برای مهار فوری محدود است و برای جلوگیری از عود کافی نیست.',
'reasons':['فنی‌توئین وریدی اگر Mg کنترل نکند خط دوم است.','دیازپام فقط مهار فوری است و برای پیشگیری از عود کافی نیست.','سولفات منیزیم وریدی خط اول است؛ پاسخ صحیح.','فنوباربیتال فقط در تشنج مقاوم به منیزیم کنکاش می‌شود.']},
(28,143):{'topic':'msafpNotIncreased','lead':'افزایش آلفا-فیتوپروتئین سرم مادر برای نقص لولهٔ عصبی، گاستروشسیس و مرگ جنین اتفاق می‌افتد ولی دیابت بارداری رابطهٔ مشخص افزایشی با آن ندارد.',
'interpretation':'مثلث افزایش MSAFP به‌خاطر نشتی مخاط/پوست جنین (NTD، گاستروشسیس، انسفالوسلی) یا تداخل‌های فیزیولوژیک-پاتولوژیک (مرگ جنین، چندقلویی) رخ می‌دهد؛ دیابت بارداری تنها تغییر در وزن جنین و پرزهای سوختگی را به‌طور غیراختصاصی می‌دهد و جزو علل کلاسیک افزایش MSAFP محسوب نمی‌شود.',
'reasons':['نقص لولهٔ عصبی علت کلاسیک افزایش MSAFP است.','دیابت بارداری جزو علل افزایش MSAFP نیست؛ پاسخ صحیح (استثنا).','مرگ داخل‌رحمی جنین علت کلاسیک افزایش MSAFP است.','گاستروشسیس نیز علت کلاسیک افزایش MSAFP است.']},
(28,144):{'topic':'sgaDefinition','lead':'SGA یعنی وزن تخمینی نوزاد/جنین کم‌تر از پرسنتایل دهم برای سن بارداری.',
'interpretation':'تعریف SGA (کوچک برای سن بارداری) مبتنی بر وزن کمتر از گزینهٔ دهم برای کریوهای مربوط به سن بارداری (حتی در غیاب علت علنی) است؛ آستانهٔ دیگر پرسنتایل (مثل ۲۰) نیز گاهی در اجماع‌ها آمده اما قرارداد استاندارد همان دهم است و سنجهٔ دور شکم معم (AC) در تعاریف IUGR مکمل است نه تعریف SGA.',
'reasons':['کم‌تر از پرسنتایل ۲۰ آستانهٔ متعارف نیست.','کم‌تر از پرسنتایل ۱۰ تعریف استاندارد SGA است؛ پاسخ صحیح.','بیش‌تر از پرسنتایل ۱۰ برای دور شکم تعریف SGA نیست.','بیش‌تر از پرسنتایل ۲۰ نیز تعریف SGA نیست.']},
(28,145):{'topic':'creasyCriteria','lead':'در معیار Creasy برای زایمان زودرس، تغییر سرویکس کلیدی است؛ «افاسمان بیش از ۸۰٪» از اجزای امتیازدهنده است.',
'interpretation':'جدول امتیاز Creasy زایمان زودرس انقباضات رحمی (مثل ≥۴ بار در ۲۰ دقیقه یا ≥۸ بار در ۶۰ دقیقه)، تغییرات سرویکس (دیالتاسیون بیش از ~۱-۲ سانتی‌متر یا افاسمان بیش از ۸۰٪)، خون‌ریزی خفیف واژینال و خروج ترشح مخاطی را امتیازی می‌کند و در سناریوی این بیمار «افاسمان>۸۰٪» از سه معیار فاکتوره است؛ دو گزینهٔ دیالتاسیون و انقباض در شرکت «۴٦ انقباض در ۴۰ دقیقه» مطابق تعریف نوشته نشده‌اند و بنابراین جزء شیوهٔ این کلید نیستند.',
'reasons':['دیالتاسیون بیش از ۱ سانتی‌متر در نولی‌پار به‌تنهایی جزء روشن این فرمول نیست و معمولاً افاسمان یا ترکیب هر دو اهمیت دارد.','دیالتاسیون>۲cm در مولتی‌یار گزینهٔ کلیدی این فرمول نیست.','افاسمان>۸۰٪ یکی از اجزای امتیازبخش معیار است؛ پاسخ صحیح.','شمارش انقباض در ۴۰ ثانیه نادرست تدوین شده و جزء معیار نیست.']},
(28,146):{'topic':'lateDecel','lead':'تفسیر افت ضربان که بعد از شروع انقباض رخ داده و بعد از پایان انقباض به خط پایه برمی‌گردد: Late Deceleration (نشانهٔ کم‌خونی جفت‌جنین).',
'interpretation':'سه نوع افت ضربان قلب جنینی بر اساس رابطهٔ زمانی با انقباض تعریف می‌شود: زودرس قرین با قلهٔ انقباض شروع و پایان می‌یابد و عارضه‌خیر است، دیررس پس از شروع انقباض آغاز و پس از پایان انقباض تمام می‌شود و هشدار کم‌اکسیژنی است و متغیر الگوی غیرثابت دربند ناف است؛ متن این بیمار (کاهش پس از شروع انقباض و برگشت پس از اتمام انقباض) با دیررس سازگار است.',
'reasons':['افت زودرس قرین با قلهٔ انقباض شروع و پایان می‌یابد و بی‌خطر است.','افت دیررس با این الگوی زمانی مشخص تعریف می‌شود؛ پاسخ صحیح.','افت متغیر رابطهٔ زمانی ثابت با انقباض ندارد.','افت طولانی‌مدت اصطلاح این الگوی زمانی نیست.']},
(28,147):{'topic':'nstReactive','lead':'دو افزایش ضربان قلب جنینی (۱۵ و ۲۵ ضربه) با طول (۱۵ و ۲۰ ثانیه) در NST ۳۶ هفته: سازهٔ استاندارد «واکنشی» بودن و نشانهٔ سلامت فعلی جنین است.',
'interpretation':'NST واکنشی زمانی است که در ۲۰ دقیقه حداقل دو acceleration با ابعاد (≥۱۵ ضربه بالای خط پایه به‌مدت ≥۱۵ ثانیه در جنین‌های ≤۳۲ هفته مثل ≥۱۰ ضربه) مشاهده شود؛ در سن ۳۶ هفته این دستاورد به‌منزلهٔ «واکنشی» تلفی می‌شود و هشدار نکست/تکرار لازم نیست؛ «غیرواکنشی» بودن یاست ایجا نبودن این شاخص‌ها معنی می‌دهد و ضعف پرفیوژن جفت با کاهش/افت‌ها در سایه‌نامه دیده می‌شود نه با acceleration.',
'reasons':['غیرواکنشی با نبود این معیارها تعریف می‌شود.','NST با این استفاده‌ها واکنشی است؛ پاسخ صحیح.','نشان‌دهندهٔ پرفیوژن ناکافی جفت نیست.','تکرار فوری NST در نتیجهٔ واکنشی لازم نیست.']},

(28,148):{'topic':'pphAsthmaCarboprost','lead':'در درمان آتونی رحمی بیمار آسمیک، پروستاگلاندین F2a (کاربوپروست) به‌خاطر خطر برونکواسپاسم ممنوع است؛ اکسی‌توسین و ارگونوین (با احتیاط) و ترنکزامیک اسید جایگزین‌های قابل‌قبول‌اند.',
'interpretation':'در خط دوم خون‌ریزی پس از زایمان، سه یوتروتونیک معمول (اکسی‌توسین، متیل‌ارگونوین، کاربوپروست PGF2a) کاربرد دارند و F2a به‌علت اثر بروکواسپاسم در آسم ممنوع است و در این بیمار نباید استفاده شود؛ ترکیب فاکتور هفت نوترکیب برای آتونی نیست و اکسی‌توسین در آسم منع ندارد.',
'reasons':['اکسی‌توسین در بیمار آسمیک منع مصرف ندارد.','متیل‌ارگونوین در فشارخون بالا ممنوع است نه در آسم.','کاربوپروست (PGF2a) در آسم ممنوع است؛ پاسخ صحیح.','فاکتور هفت نوترکیب برای همولایز و DIC خاص است نه آتونی.']},
(28,149):{'topic':'gdmTwoStepOgt','lead':'تست غربالگری ۵۰ گرمی مثبت (۱۶۰ میلی‌گرم/دسی‌لیتر در ۲۴ هفته): قدم بعدی تست خوراکی ۱۰۰ گرمی سه‌ساعته (OGTT) برای تشخیص قطعی GDM است.',
'interpretation':'برنامهٔ غربالگری دوپله در ۲۴-۲۸ هفته با تست ۵۰ گرمی (GCT) آستانهٔ ~۱۴۰ میلی‌گرم است و نتیجهٔ ۱۶۰ به‌معنای غربالگری مثبت است و باید با تست توییدی سه‌ساعتهٔ ۱۰۰ گرمی (با آستانه‌های مشخص در ۴ نقطه) رد یا تأیید شود؛ شروع انسولین پیش از تشخیص غلط است و رژیم صرف در این مرحله به‌جای تثبیت تشخیص نمی‌شود و تکرار ۵۰ گرمی پروتکل معتبر نیست.',
'reasons':['انسولین فقط پس از تأیید و در صورت نیاز است.','انجام OGTT ۱۰۰ گرمی سه‌ساعته قدم درست است؛ پاسخ صحیح.','رژیم دیابتی به‌تنهایی تشخیص را تأیید نمی‌کند.','تکرار تست ۵۰ گرمی پروتکل استاندارد نیست.']},
}
